def can_trade_symbol(symbol: str, cooldown_minutes: int = 45) -> bool:
    """
    NUANCE #5: Check if symbol is in cooldown
    Prevents HINDALCO loop (revenge trading)
    """
    if symbol not in symbol_cooldowns:
        return True

    time_since_exit = time.time() - symbol_cooldowns[symbol]
    if time_since_exit < cooldown_minutes * 60:
        return False

    return True


def should_trade_now(current_time: datetime) -> bool:
    """
    NUANCE #9: Session timing checks
    Block trades in lunch lull (11:30-13:00)
    """
    hour = current_time.hour
    minute = current_time.minute

    # Convert to minutes since market open (9:15 = 0)
    minutes_since_open = (hour - 9) * 60 + (minute - 15)

    # Block lunch lull (11:30-13:00)
    if 135 <= minutes_since_open < 225:
        return False

    # Before market open or after close
    if minutes_since_open < 0 or minutes_since_open > 375:
        return False

    return True


def round_to_tick(price: float, tick_size: float) -> float:
    """
    NUANCE #1: Tick size rounding
    90% of order rejections are due to this
    """
    return round(price / tick_size) * tick_size


